from pathlib import Path
import json,html
r=Path('assets-src/design-pass/kit/city/street-life');a=json.loads((r/'layout-inputs.json').read_text());report=json.loads((r/'layout-preflight.json').read_text());layout=a['layout'];p=a['plan'];svg=[]
def rect(x,z,w,d,attrs):svg.append(f'<rect x="{x}" y="{z}" width="{w}" height="{d}" {attrs}/>')
rect(-55,-37.5,110,75,'fill="#e2ead0" rx="1"')
