for l in a['paths']:
 pts=' '.join(f'{x},{z}' for x,z in l['points']);svg.append(f'<polyline points="{pts}" fill="none" stroke="#b46560" stroke-width=".4" stroke-dasharray="1 .7"><title>{l["name"]}</title></polyline>')
for i,item in enumerate(layout['items']):
 x,z=item['position'];w,h,d=item['xyz'];x0,z0,x1,z1=item['pad'];rect(x0,z0,x1-x0,z1-z0,'fill="#d6edf7" stroke="#23748e" stroke-width=".25"');rect(x-w/2,z-d/2,w,d,'fill="#176a72"');svg.append(f'<circle cx="{x}" cy="{z-3.2}" r="1.6" fill="#fff" stroke="#176a72" stroke-width=".25"/><text x="{x}" y="{z-2.6}" text-anchor="middle" font-size="1.8" fill="#173d45">{i+1}</text>')
svg='<svg role="img" aria-label="Схема трёх предложенных мест: киоск мороженого, цветы, остановка" viewBox="-57 -40 114 80" xmlns="http://www.w3.org/2000/svg">'+''.join(svg)+'</svg>'
